2	using MapEdit;
3	using Microsoft.Xna.Framework;
4	using ProjectTower.texturesheet;
5	namespace ProjectTower.particles.particles.hit;
6	internal class ArrowTrail : BaseParticle
7	{
8	 public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
9	 {
10	 p.loc = loc;
11	 p.traj = traj;
12	 p.size = Rand.GetRandomFloat(0.1f, 0.2f);
13	 p.flags = Rand.GetRandomInt(1, 5);
14	 p.owner = owner;
15	 p.frame = Rand.GetRandomFloat(0.1f, 0.5f);
16	 p.rotation = Trig.GetAngle(default, traj);
17	 p.rDir = Rand.GetRandomFloat(-1f, 1f);
18	 base.Init(p, loc, traj, size, rotation, flags, owner);
19	 }
20	 public override void Update(Particle p, float frameTime)
21	 {
22	 p.rotation += p.rDir * frameTime;
23	 base.Update(p, frameTime);
24	 }
25	 public override void Draw(Particle p, float brite)
26	 {
27	 float num = p.frame * 0.5f;
28	 if (num > 1f)
29	 {
30	 num = 1f;
31	 }
32	 ScrollManager.GetScreenLoc(p.loc, 0);
33	 Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), p.flags, new Vector2(10f, 1f) * ScrollManager.cannedDepth[0] * p.size, p.rotation, 1f, 1f, 1f, num);
34	 }
35	}
