40	namespace ProjectTower.particles.particles.hit;
41	public class ElementalBit : BaseParticle
42	{
43	 public override void Init(Particle p, Vector2 loc, Vector2 traj, float size, float rotation, int flags, int owner)
44	 {
45	 p.loc = loc;
46	 p.rotation = rotation;
47	 p.flags = flags;
48	 p.traj = traj;
49	 p.frame = Rand.GetRandomFloat(0.1f, 0.2f);
50	 size *= 100f;
51	 switch (flags)
52	 {
53	 case 1:
54	 p.size = Rand.GetRandomFloat(0f, 1f) * size;
55	 p.loc += Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 10f;
56	 p.traj *= -10f;
57	 p.rDir = Rand.GetRandomFloat(-1f, 1f);
58	 p.aux = Rand.GetRandomInt(5, 9);
59	 break;
60	 case 2:
61	 p.size = Rand.GetRandomFloat(0f, 1f) * size;
62	 p.loc += Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 10f;
63	 p.traj *= -10f;
64	 p.rDir = Rand.GetRandomFloat(-1f, 1f);
65	 break;
66	 case 3:
67	 p.size = Rand.GetRandomFloat(0f, 1f) * size;
68	 p.loc += Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 10f;
69	 p.traj *= -10f;
70	 p.rDir = Rand.GetRandomFloat(-1f, 1f);
71	 p.aux = Rand.GetRandomInt(1, 5);
72	 break;
73	 case 4:
74	 p.size = Rand.GetRandomFloat(0f, 1f) * size;
75	 p.loc += Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 10f;
76	 p.traj *= -10f;
77	 p.rDir = Rand.GetRandomFloat(-1f, 1f);
78	 p.aux = Rand.GetRandomInt(1, 5);
79	 break;
80	 case 5:
81	 p.size = Rand.GetRandomFloat(0f, 1f) * size;
82	 p.loc += Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 10f;
83	 p.traj *= -10f;
84	 p.rDir = Rand.GetRandomFloat(-1f, 1f);
85	 p.aux = Rand.GetRandomInt(1, 5);
86	 break;
87	 case 6:
88	 p.size = Rand.GetRandomFloat(0f, 1f) * size;
89	 p.loc += Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 10f;
90	 p.traj *= -10f;
91	 p.rDir = Rand.GetRandomFloat(-1f, 1f);
92	 p.aux = Rand.GetRandomInt(1, 5);
93	 break;
94	 }
95	 p.owner = owner;
96	 base.Init(p, loc, traj, size, rotation, flags, owner);
97	 }
98	 public override void Update(Particle p, float frameTime)
99	 {
100	 TrimFrame(p);
101	 p.frame -= frameTime;
102	 p.loc += p.traj * frameTime;
103	 if (p.frame <= 0f)
104	 {
105	 p.exists = false;
106	 }
107	 }
108	 public override void Draw(Particle p, float brite)
109	 {
110	 switch (p.flags)
111	 {
112	 case 1:
113	 Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), p.aux, new Vector2(2f, 1f) * ScrollManager.cannedDepth[0] * 0.05f * p.size, p.rotation, 1f, 1f, 1f, p.frame * 1f);
114	 break;
115	 case 2:
116	 Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), Rand.GetRandomInt(56, 59), new Vector2(2f, 1f) * ScrollManager.cannedDepth[0] * 0.05f * p.size, p.rotation, 1f, 1f, 1f, p.frame * 1f);
117	 break;
118	 case 3:
119	 Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), p.aux, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * p.size * 0.125f, p.rotation, 0.35f, 0.9f, 0.2f, p.frame * 1f);
120	 break;
121	 case 4:
122	 Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), p.aux, new Vector2(1f, 1f) * ScrollManager.cannedDepth[0] * p.size * 0.125f, p.rotation, 1f, 1f, 1f, p.frame * 1f);
123	 break;
124	 case 5:
125	 Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(p.loc, 0), p.aux, new Vector2(2f, 1f) * ScrollManager.cannedDepth[0] * p.size * 0.1f, p.rotation, 1f, 0.9f, 0.8f, p.frame * 1f);
126	 break;
127	 case 6:
