146	 p.frame = Rand.GetRandomFloat(0.4f, 0.6f);
147	 p.rDir = 0f;
148	 switch (p.flags)
149	 {
150	 case 1:
151	 p.rDir = Rand.GetRandomFloat(-10f, 10f);
152	 p.traj.Y = Rand.GetRandomFloat(-100f, 0f);
153	 p.aux = Rand.GetRandomInt(5, 9);
